function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

function slug(value, fallback = '') {
  return String(value || fallback || '').trim();
}

const body = $json.body || {};
const avatar = slug(body.avatar);

const slugRegex = /^[a-z0-9][a-z0-9-]*$/i;

if (!slugRegex.test(avatar)) {
  return {
    json: {
      ok: false,
      skipQuery: true,
      error: 'avatar is required and must be a slug-like value',
      request: { avatar }
    }
  };
}

const baseUrl = slug(
  body.baseUrl || body.base_url,
  'http://192.168.0.194:9000'
).replace(/\/$/, '');

const query = `
WITH canonical AS (
  SELECT *
  FROM canonical_asset_registry
  WHERE avatar = ${sql(avatar)}
    AND COALESCE(status, '') IN ('canonical', 'selected')
    AND (
      COALESCE(is_canonical, false) = true
      OR status = 'canonical'
    )
  ORDER BY created_at DESC
  LIMIT 12
),
selected AS (
  SELECT *
  FROM canonical_asset_registry
  WHERE avatar = ${sql(avatar)}
    AND COALESCE(status, '') = 'selected'
    AND COALESCE(is_canonical, false) = false
  ORDER BY created_at DESC
  LIMIT 24
)
SELECT
  ${sql(avatar)} AS avatar,
  COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'assetId', asset_id,
          'avatar', avatar,
          'scene', scene,
          'assetType', asset_type,
          'status', status,
          'isCanonical', is_canonical,
          'bucket', bucket,
          'objectPath', object_path,
          'url', ${sql(baseUrl)} || '/' || bucket || '/' || object_path,
          'mimeType', mime_type,
          'metadata', metadata,
          'createdAt', created_at
        )
      )
      FROM canonical
    ),
    '[]'::jsonb
  ) AS canonical_assets,
  COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'assetId', asset_id,
          'avatar', avatar,
          'scene', scene,
          'assetType', asset_type,
          'status', status,
          'isCanonical', is_canonical,
          'bucket', bucket,
          'objectPath', object_path,
          'url', ${sql(baseUrl)} || '/' || bucket || '/' || object_path,
          'mimeType', mime_type,
          'metadata', metadata,
          'createdAt', created_at
        )
      )
      FROM selected
    ),
    '[]'::jsonb
  ) AS selected_assets;
`;

return {
  json: {
    ok: true,
    skipQuery: false,
    query
  }
};

const row = $input.first()?.json || {};

function parse(value, fallback) {
  if (value === undefined || value === null) return fallback;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return fallback;
    }
  }
  return value;
}

const avatar = row.avatar;
const canonicalAssets = parse(row.canonical_assets, []);
const selectedAssets = parse(row.selected_assets, []);

const identity = {
  displayName: 'Estefanía Montealegre',
  avatar,
  identityPrompt:
    'Estefanía Montealegre, Colombian woman, warm natural beauty, trigueña skin, natural curly hair, olive-green eyes, elegant but approachable presence, realistic skin texture, cinematic lifestyle photography, consistent identity.',
  consistencyRules: [
    'Keep the same facial identity across scenes.',
    'Use natural curly hair unless the scene explicitly requires a styled variation.',
    'Avoid exaggerated luxury, plastic skin, overprocessed makeup, or unrealistic body proportions.',
    'Prefer candid lifestyle realism over fashion campaign posing.'
  ],
  visualAnchors: [
    'trigueña skin',
    'natural curly hair',
    'olive-green eyes',
    'warm confident expression',
    'natural cinematic realism'
  ]
};

return [
  {
    json: {
      ok: true,
      resolved: true,
      avatar,
      identity,
      canonicalAssets,
      selectedAssets,
      assetCount: {
        canonical: canonicalAssets.length,
        selected: selectedAssets.length
      }
    }
  }
];
